-- Event recordings: one row per finished MP4 clip in the recordings
-- directory. file_name is a bare name generated by minicam, never a path.
-- camera_name is not a foreign key: cameras live in config.toml, and a clip
-- outlives its camera until retention deletes it. classes is a JSON array
-- of the detection classes seen while the clip was recording.
CREATE TABLE recordings (
    id                INTEGER PRIMARY KEY AUTOINCREMENT,
    camera_name       TEXT NOT NULL,
    file_name         TEXT NOT NULL UNIQUE,
    started_at        TEXT NOT NULL,
    duration_seconds  REAL NOT NULL CHECK (duration_seconds >= 0),
    size_bytes        INTEGER NOT NULL CHECK (size_bytes >= 0),
    classes           TEXT NOT NULL DEFAULT '[]',
    created_at        TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);
CREATE INDEX idx_recordings_camera ON recordings(camera_name, id);
